from pathlib import Path
import sys,json
import numpy as np,pandas as pd
ROOT=Path(__file__).resolve().parents[3];sys.path.insert(0,str(ROOT/'src'))
from geas35.models.transition.handoff_b60_r6_v1 import sha
D=ROOT/'experiments/rl_policy_training/artifacts/strawberry_support_coverage_audit_v1';P=ROOT/'experiments/rl_policy_training/artifacts/vent_command_carry_b60_r6_v1/strawberry';S=ROOT/'experiments/rl_policy_training/artifacts/step15_b60_r6_v1/strawberry'
def read(p):return json.loads(p.read_text())
def write(p,x):p.write_text(json.dumps(x,indent=2,ensure_ascii=False,default=str)+'\n')
def table(f):
 f=f.copy()
 for c in f:
  if pd.api.types.is_float_dtype(f[c]):f[c]=f[c].map(lambda x:f'{x:.6g}')
 return '\n'.join(['| '+' | '.join(f.columns)+' |','| '+' | '.join(['---']*len(f.columns))+' |']+['| '+' | '.join(map(str,r))+' |' for r in f.itertuples(index=False,name=None)])
pro=read(D/'protocol.json');assert sha(D/'protocol.json')==read(D/'protocol_lock.json')['sha256']
for r in pro['inputs']:assert sha(ROOT/r['path'])==r['sha256'],r['path']
f=pd.read_csv(D/'case_classification.csv');cells=pd.read_csv(D/'joint_cells.csv');dist=pd.read_csv(D/'distance_pools.csv');marginal=pd.read_csv(D/'marginal_ranges.csv');strata=pd.read_csv(D/'population_strata.csv');neighbors=pd.read_parquet(D/'nearest_50_neighbors_all_pools.parquet');appendix=pd.read_csv(D/'clean_rollout5_start_coverage_appendix.csv');complete=read(D/'audit_complete.json');config=read(S/'state_action_support.json')
for split in ('train','validation'):
 physical=pd.read_parquet(P/(split+'_physical.parquet'));scaled=pd.read_parquet(P/(split+'_scaled.parquet'));assert physical.row_id.equals(scaled.row_id)
assert len(f)==39 and len(appendix)==5
for row in f.to_dict('records'):
 assert row['full_train_radius_count']==row['reference_episode_pool_radius_count']+row['heldout_calibration_episode_pool_radius_count']
 assert row['reference_episode_pool_radius_count']==row['reference_radius_count']+row['neighbors_lost_by_reference_row_sampling']
 assert row['reference_radius_count']<50
# Consolidated distances include the old threshold for context only.
wide=dist.pivot(index='episode_index',columns='pool',values=['nearest','k50','within_common_radius']);wide.columns=['_'.join(x) for x in wide.columns];wide=wide.reset_index().merge(f[['episode_index','timestamp','DAT','fourway_class']],on='episode_index');wide['frozen_reference_severe_threshold']=config['thresholds']['state_severe'];wide.to_csv(D/'distance_comparison_wide.csv',index=False)
rolling=cells.loc[cells.combination.str.startswith('rolling_context:')].copy();rolling['feature']=rolling.combination.str.removeprefix('rolling_context:');rolling=rolling.merge(marginal[['episode_index','feature','outside_full_train_range']],on=['episode_index','feature']);rolling['classification']=np.where(rolling.outside_full_train_range,'outside_marginal_range',np.where(rolling.full_train.eq(0),'in_range_but_context_cell_absent',np.where(rolling.full_train.lt(50),'in_range_context_cell_sparse','marginal_and_context_cell_covered_ge50')));rolling.to_csv(D/'rolling_marginal_vs_joint.csv',index=False)
rs=rolling.groupby(['feature','classification']).size().rename('cases').reset_index();rs.to_csv(D/'rolling_classification_summary.csv',index=False)
js=cells.groupby('combination').agg(full_train_zero=('full_train',lambda x:int((x==0).sum())),full_train_1_to49=('full_train',lambda x:int(((x>0)&(x<50)).sum())),reference_zero=('reference',lambda x:int((x==0).sum())),validation_median=('validation','median')).reset_index();js.to_csv(D/'joint_coverage_summary.csv',index=False)
sampling=f.loc[f.full_train_radius_count.ge(50)].copy();split_limited=int(sampling.reference_episode_pool_radius_count.lt(50).sum());row_limited=len(sampling)-split_limited
sampler_summary=sampling.groupby(['series','season','month']).agg(cases=('episode_index','size'),full_neighbors=('full_train_radius_count','median'),reference_neighbors=('reference_radius_count','median'),holdout_loss=('neighbors_lost_by_episode_holdout','median'),row_sampling_loss=('neighbors_lost_by_reference_row_sampling','median')).reset_index();sampler_summary.to_csv(D/'sampling_gap_bias_summary.csv',index=False)
# Pool-neighbor origins: don't imply the absent Validation series exists in Train.
origins=neighbors.loc[neighbors.pool.eq('full_train')].groupby(['episode_index','train_series_id','train_source_confidence','train_season','train_year_month','train_DAT_30d']).size().rename('nearest50_rows').reset_index();origins.to_csv(D/'nearest_train_origin_summary.csv',index=False)
category=pd.read_csv(D/'overlapping_category_counts.csv');descriptions={'A':'full Train 반경 내<50','B':'full Train>=50, reference<50','C':'source/series/DAT 또는 series×season×month 미관측','D':'previous/current command 관련 joint cell<50','E':'weather/context joint cell<50','F':'rolling×context joint cell<50','G':'복수 flag 또는 미분리'};category['definition']=category.category.map(descriptions)
summary={**complete,'diagnostic_radius':config['thresholds']['state_severe'],'full_train_zero_neighbors':int(f.full_train_radius_count.eq(0).sum()),'missing_train_series_cases':int(f.missing_series.sum()),'sampling_gap_after_episode_holdout_below50':split_limited,'sampling_gap_after_row_sampling_below50':row_limited,'recommendation':'Maintain Train coverage limitation and predefine a restricted RL research domain; proposal only, not implemented','formal_support_sampling_or_geometry_change_approved':False,'clean5_relative_start_margin_range':[float(appendix.relative_margin.min()),float(appendix.relative_margin.max())]};write(D/'final_gate.json',summary)
lines=['# Strawberry fixed-Train support coverage audit', '\n**strawberry Step16 BLOCKED / 전체 Step17 BLOCKED 유지.** 비학습 감사만 완료했다. dataset/scaler/model/support feature/weights/threshold/reward 변경, support 재생성, sampling 변경, model fit, Test, PPO, Step17–19, Step19.5/HPO 모두 실행하지 않았다.',f"\n39건 중 **23건은 전체 eligible Train에도 진단 반경 내 이웃이50개 미만**이고 그중20건은0개다. **16건은 full Train에50개 이상 있지만 reference에는 부족**하다. 16건 중6건은 사전 정의한 추가 domain/joint 결손 flag가 없고,10건은 그 결손도 함께 있어 복합으로 분류했다. reference 재설계만으로39건 전체를 해결할 근거는 없다.", '\n## 거리 비교와 판정 범위',f"공식55 scaled observation, 기존 weights, Euclidean k50를 그대로 사용했다. severe={config['thresholds']['state_severe']:.12f}는 frozen reference 기반 calibration 값이다. 이를 **모집단 간 동일 진단 반경**으로만 사용해 이웃 수를 세었다. full Train 또는 calibration의 k50가 낮아도 공식 PASS를 부여하지 않는다. 반경 내50개는 이번 진단의 동일 k 기준이며 새로운 admission 기준이 아니다.",'\nfull eligible Train, frozen reference, 실제 sampled calibration, reference-eligible episode 전체, heldout calibration episode 전체를 각각 계산했다. [39건 나란한 nearest/k50/반경 count](distance_comparison_wide.csv). sampled calibration과 heldout episode 전체는 다른 모집단이다.',table(wide[['episode_index','nearest_full_train','k50_full_train','nearest_reference','k50_reference','nearest_calibration_sample','k50_calibration_sample','fourway_class']]),'\n4-way 진단 분류에서 data gap은 full 반경 count<50 또는 source/series 미관측 또는 사전 정의 core joint cell0이다. sampling gap은 full>=50/ref<50이다. 두 조건이 모두 있으면 both다. core joint cell0은 quantile 구간 기준의 관측 부재이며 물리적으로 불가능함이나 전체55차원 반경 내 이웃이 없다는 뜻과 다르다. [사전 규칙](protocol.json), [고정 bin 경계](joint_bin_edges.json).','\n## source / series / 생육기 / 시기', 'Train은44,097행이며 source_confidence는 모두 legacy_command_snapshot_assumption, series는 strawberry_geas2_0뿐이다. Validation은 같은 legacy 신뢰도 표기지만 geas2_0와 geas2_5 두 series다.39건 중19건은 Train에 없는 geas2_5에서 발생했고 이19건 중14건은 full Train 진단 반경 내 이웃0이다. 같은 source confidence가 같은 생육기·수집 조건을 보장하지 않는다. legacy 값이 실제 전송 timestamp 복원이라는 뜻도 아니다.','\nmonth/season은 KST 기록 날짜, DAT는30일 구간, day/night는 기존 obs_is_daytime, greenhouse period는 기존 series+segment의 metadata proxy로만 정의했다. 실제 재배 cycle의 외부 명세로 확정한 구분이 아니다. segment/year-month/episode는 시간 분리상 naturally unseen일 수 있으므로 그 사실만으로 물리적 domain shift라고 단정하지 않았다. [전체 층별 모집단/비율](population_strata.csv), [query 동일 층 count](query_strata.csv), [전체 pool nearest50 원본 행](nearest_50_neighbors_all_pools.parquet), [가장 가까운 Train 시기](nearest_train_origin_summary.csv).','\n## weather/context와 command joint coverage',table(js.loc[~js.combination.str.startswith('rolling_context:')]),'\n위 count는39개 query의 해당 cell 중 결손/희소가 관측된 **사례 수**다. [joint_cells.csv](joint_cells.csv)는 각 query cell별 실제 full Train/reference/calibration/Validation 행수, 물리값과 bin ID를 모두 담고 있다. current command는 조합 coverage 진단에만 사용하며 공식55-state support에 추가하지 않았다.','\n실내 상태 cell에는 Train이 있는데 이전 command·DAT를 결합하면 빈 cell이 되는 사례는 case_classification.csv의 indoor_cell_count → indoor_prevvent_cell_count → indoor_prevvent_DAT_cell_count로 추적할 수 있다. 12개 current/previous command를 묶은 높은 차원 cell의 희소는 bin 해상도에도 민감하므로38건 D flag를38건의 인과적 command 오류로 해석하지 않는다.','\n## rolling/derived coverage',table(rs),'\n[marginal_ranges.csv](marginal_ranges.csv)는55개 feature의 query 물리값과 Train min/p01/p50/p99/max·Validation 범위를 제공한다. [rolling_marginal_vs_joint.csv](rolling_marginal_vs_joint.csv)는 단독 범위 밖과 DAT/day/target context 결합에서만 absent/sparse인 경우를 분리한다. DLI, light sum, low-VPD/RH90, degree, ACH, condensation, tempdiff 계산 정의는 변경하지 않았다. 이전3121시점 teacher forcing all55 parity PASS가 그대로 유지되므로 이번 결손을 runtime 계산식 오류로 새로 판정하지 않는다.','\n## reference sampling 영향',f"전체 Train>=50/reference<50인16건 중 **{split_limited}건은 calibration episode holdout 후 참조 후보 pool부터50개 미만**, **{row_limited}건은 후보 pool에50개 이상 있지만 고정 row sampling 후50개 미만**이다. 각 case의 full 이웃 수=참조 후보 pool+heldout episode 이웃 수이고, 참조 후보 pool=최종reference+row sampling 탈락 수임을 검증했다. 참조량 감소는 기존 설계의 결과이며 이 숫자만으로 sampler 구현 오류나 calibration 실패를 뜻하지 않는다.",table(sampler_summary),'\n참조 sampling 격차16건은3월10건·4월1건·10월1건·11월4건이다. geas2_0 후기 DAT180–215와 geas2_5 초기 DAT11–25에 나타난다. 가장 가까운 Train는 모두 geas2_0/legacy에서 온다. 이러한 query 편향과 전체 reference의 계절별 표본 비율은 서로 다른 통계로 보존했다. [sampling case 층화](query_sampling_gap_strata.csv).','\n## 최종 A–G 분류 (중복 허용)',table(category),'\nA–G는 상호배타적 원인 판정이 아니라 사전 고정한 coverage evidence flag다. 합이39가 아니다. source/season 조건과 command·weather·rolling joint sparsity가 겹친다. 대표 case의 물리값·neighbor 출처·거리·count는 case_classification.csv와 연결된다. 공식 feature geometry가 잘못됐다고 확정할 증거는 없으며, high-dimensional sparse cell만으로 feature 삭제를 권장하지 않는다.','\n## clean rollout5 시작 상태 부록',table(appendix),'\n5건의 시작 reference severe 상대 여유는24.87–40.58%다. 모두 기존 state warning threshold보다도 낮다. 처음부터 severe 경계에 거의 붙어 있었다는 설명만으로 이5건의 후속 이탈을 설명하기 어렵다. 39건 coverage 통계에 섞지 않았으며 teacher-normal/free-only severe의 Transition/누적 오차 판정은 유지한다. 모델을 재학습하지 않았다.','\n## 다음 최소 변경 조치 — 하나', '**Train coverage 문제를 limitation으로 유지하고, RL 연구 domain 제한을 사전 정의하는 계약 설계**를 추천한다. 특히 full Train에도 이웃이 없는 시기/series·환경·command 조건을 적용 가능한 범위와 구분해야 한다. 이는 다음 작업 제안이며 이번 감사에서 데이터/episode를 제외하거나 실행 domain을 바꾸지 않았다. Validation 결과가 좋아지는 구간만 사후 선택해서 기존 Step16을 PASS로 바꾸면 안 된다. 새 범위를 검토한다면 Train-only 근거로 먼저 동결하고 전체 원래 Validation의 out-of-domain 비율·실패도 계속 보고하는 별도 연구 프로토콜이 필요하다.', '\nreference sampling 재설계는16건 일부에 영향을 줄 수 있지만23건의 full Train 부족과 별도 clean5 누적 이탈을 해결하지 못하므로 최우선 단독 조치로 선택하지 않았다. domain 제한 설계도 곧바로 Step17 진입을 뜻하지 않는다. clean5 Transition rollout 문제와 OOD 해결 후 PPO 전 reward audit는 독립 후속 제한으로 남는다. 온도 penalty≈99%·딸기 종료비용92.40% flag도 유지한다.','\n물리적 online actuator-safe fallback BLOCKED 유지. 원본 해시 전후 동일. [최종 감사 상태](final_gate.json), [각 사례 분류](case_classification.csv).']
