lines.insert(3,f"\n실내 T/RH/CO₂ 조합 cell에 full Train50행 이상이 있지만 previous vent를 결합하면50행 미만이 되는 사례는{command_counts['indoor_cell_ge50_but_with_prevvent_lt50']}건, previous vent와 DAT까지 결합하면{command_counts['indoor_cell_ge50_but_with_prevvent_DAT_lt50']}건이다. 단변량 indoor range가 겹친다는 사실만으로 command/context를 포함한55-feature joint coverage를 보장하지 않는다.")
(D/'final_decision_ko.md').write_text('\n'.join(lines)+'\n');write(D/'report_code_manifest.json',{str(Path(__file__).relative_to(ROOT)):sha(Path(__file__))})
